//// Created by Dzmitryj Bareika on 5.01.25.//#include "pico/stdlib.h"#include "sx127x.h"#include <etl/vector.h>#include <etl/string.h>#include <bitset>SX127X::SX127X radio = SX127X::SX127X(spi1, 12, 15, 14, 13, 6, 7);constexpr uint8_t to_uint8(uint8_t value) {  return value & 0xFF; // Ensures only the lower 8 bits are kept.}constexpr uint32_t to_uint32(uint32_t value) {  return value & 0xFFFFFFFF; // Ensures only the lower 32 bits are kept.}etl::vector<uint8_t, 256> encodeScrambler(const etl::vector<uint8_t, 256>& data) {  uint32_t reg = 0xAAAAAAAA;  etl::vector<uint8_t, 256> res;  for (auto data_byte : data) {    data_byte ^= ((reg >> 4) ^ (reg >> 9)) & 0xFF; // Mimic Python's bitwise behavior    data_byte = to_uint8(data_byte);    reg = (reg << 8) | data_byte;    reg = to_uint32(reg);    res.push_back(data_byte);  }  return res;}constexpr uint8_t NRZI_ENCODE_TABLE[16] = {0xA, 0xB, 0x9, 0x8, 0xD, 0xC, 0xE, 0xF, 0x5, 0x4, 0x6, 0x7, 0x2, 0x3, 0x1, 0x0};// Convert a list of hexadecimal values to binary string representationetl::string<256> hex_to_bin(const etl::vector<uint8_t, 256>& hl) {  etl::string<256> binary_result;  for (uint8_t hex_val : hl) {    std::bitset<8> binary(hex_val); // Convert hex to binary    auto binary_str = binary.to_string(); // Get binary string representation    for (char bit : binary_str) {      binary_result += bit; // Append each character to etl::string    }  }  return binary_result;}// Encode using simple bit stuffing for NRZIetl::vector<uint8_t, 256> encode_via_simple_stuffing(const etl::vector<uint8_t, 256>& msg) {  uint8_t last_bit = 0;  etl::vector<uint8_t, 256> res;  auto binary_msg = hex_to_bin(msg);  for (char bit_char : binary_msg) {    uint8_t input_bit = bit_char - '0'; // Convert char to int    last_bit = (input_bit ^ last_bit) & 1;    res.push_back(last_bit);  }  return res;}// Main NRZI encode functionetl::vector<uint8_t, 256> encodeNRZI(const etl::vector<uint8_t, 256>& data) {  uint8_t state = 1;  etl::vector<uint8_t, 256> res;  for (uint8_t byte : data) {    uint8_t hi = NRZI_ENCODE_TABLE[(byte >> 4) & 0xF];    uint8_t lo = NRZI_ENCODE_TABLE[byte & 0xF];    if (state != 0) {      hi ^= 0xF;    }    if (hi & 1) {      lo ^= 0xF;    }    state = lo & 1;    res.push_back((hi << 4) | lo);  }  return res;}constexpr uint8_t ONES_CAP = 0x5;constexpr uint8_t HDLC_FLAG = 0b01111110;// Reverse lookup table for reversing bitsconstexpr etl::array<uint8_t, 16> REVERSE_LOOKUP = {0x0, 0x8, 0x4, 0xc, 0x2, 0xa, 0x6, 0xe, 0x1, 0x9, 0x5, 0xd, 0x3, 0xb, 0x7, 0xf};// Helper function to reverse bits of a byteuint8_t reverse_bits(uint8_t n) {  return (REVERSE_LOOKUP[n & 0xF] << 4) | REVERSE_LOOKUP[(n >> 4) & 0xF];}// Process the result by trimming trailing zerosetl::vector<uint8_t, 256> process_viper_result(const etl::vector<uint8_t, 256>& input) {  etl::vector<uint8_t, 256> result = input;  while (!result.empty() && result.back() == 0) {    result.pop_back();  }  return result;}// Function to encode HDLC data// Main function to stuff bits for HDLC encodingvoid stuff_bits_with_viper(const etl::vector<uint8_t, 256>& input, etl::vector<uint8_t, 256>& output, int preamble_count, int trailer_count) {  uint32_t reg = 0;  uint32_t bit_count = 0;  uint32_t one_count = 0;  const uint32_t mask = 0xFF;  size_t last_idx = 0;  // Add preamble  for (int i = 0; i < preamble_count; ++i) {    reg <<= 8;    reg |= HDLC_FLAG;    output[last_idx++] = static_cast<uint8_t>((reg >> bit_count) & mask);  }  // Main loop for stuffing bits  for (size_t byte_idx = 0; byte_idx < input.size(); ++byte_idx) {    for (int bit_idx = 0; bit_idx < 8; ++bit_idx) {      uint8_t bit = (input[byte_idx] >> bit_idx) & 1;      reg <<= 1;      if (bit) {        reg |= 1;        ++one_count;      } else {        one_count = 0;      }      ++bit_count;      if (one_count == ONES_CAP) {        reg <<= 1;        ++bit_count;        one_count = 0;      }      if (bit_count >= 8) {        output[last_idx++] = static_cast<uint8_t>((reg >> (bit_count - 8)) & mask);        bit_count -= 8;      }    }  }  if (bit_count > 0) {    reg <<= (8 - bit_count);    output[last_idx++] = static_cast<uint8_t>((reg >> bit_count) & mask);  }  // Add trailer  for (int i = 0; i < trailer_count; ++i) {    reg <<= 8;    reg |= HDLC_FLAG;    bit_count += 8;    if (bit_count >= 8) {      output[last_idx++] = static_cast<uint8_t>((reg >> (bit_count - 8)) & mask);      bit_count -= 8;    }  }  output.resize(last_idx); // Trim to actual size}etl::vector<uint8_t, 256> hdlc_encode(const etl::vector<uint8_t, 256>& data, int preamble_count = 7, int trailer_count = 3) {  etl::vector<uint8_t, 256> output;  output.resize(static_cast<size_t>(std::ceil(data.size() * 1.2)) + preamble_count + trailer_count);  stuff_bits_with_viper(data, output, preamble_count, trailer_count);  return process_viper_result(output);}int main() {  if(radio.begin())    radio.setFrequency(SX127X::SX127X::FREQ_433)        ->setTXPower(17)        ->setModulationFSK(9.6, 3.0)        ->setPreambleLength(0);  const etl::vector<uint8_t, 256> Data = {0x01, 0x02, 0x03};  const etl::vector<uint8_t, 256> message = encodeNRZI(encodeScrambler(hdlc_encode(Data)));  const uint8_t message_size = message.size();  radio.setPayloadLength(message_size);  while (true) {    radio.send(message);    busy_wait_ms(1000);  }}